    "title": "2020 Human Biology Unit 1 · Q31",
    "stem": "The diagram below shows a model cell used by a student to investigate osmosis.",
    "originalStem": "The diagram below shows a model cell used by a student to investigate osmosis.",
    "searchText": "Question 31 The diagram below shows a model cell used by a student to investigate osmosis. State a material that can be used as the membrane of the model cell and describe the feature that makes it suitable to use in this experiment. Four model cells, labelled A, B, C and D, were constructed and contained 0%, 5%, 10% and 20% glucose solutions respectively. The model cells were weighed then suspended in four test tubes containing a 10% glucose solution. One hour later the model cells were removed and reweighed. In the space below, draw a labelled diagram of the experimental set up. Predict which model, A, B, C or D, would have the greatest change in mass after the given hour. Give a detailed explanation for your answer. What is the name given to the type of solution in the test tube of Model C? The student repeated the experiment three times. Describe why scientists undertake multiple tests and calculate mean results.",
    "source": "2020 Human Biology Unit 1",
    "sample": false,
    "images": [
      {
        "src": "assets/question-diagrams/7de00bd73cffca4d.png",
        "alt": "Original labelled diagram or graph for hb2020-u1-q31",
        "sourcePage": 12
      }
    ],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "State a material that can be used as the membrane of the model cell and describe the feature that makes it suitable to use in this experiment.",
        "marks": 2,
        "solution": "Fluid = all parts of the membrane are constantly moving/ not fixed in place | 1\nMosaic = the membrane is made up of many different types of molecules (proteins, phospholipids, cholesterol etc) | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-mixed-s1"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "In the space below, draw a labelled diagram of the experimental set up.",
        "marks": 4,
        "solution": "Independent variable on the LHS (cell model and glucose concentration) | 1\nDependent variable on the RHS (Change in mass). ½ only if the last column is not included. | 1\nUnits included | 1\nTable heading including both variables | 1\nCell Model | Glucose solution concentration (%) | Initial Mass (g) | Final Mass (g) | Change in Mass (g)\nA | 0\nB | 5\nC | 10\nD | 20",
        "questionTypes": [
          "short_answer",
          "diagram"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-mixed-s1"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "c",
        "type": "written",
        "prompt": "Predict which model, A, B, C or D, would have the greatest change in mass after the given hour. Give a detailed explanation for your answer.",
        "marks": 5,
        "solution": "Model D | 1\nGlucose molecules are large so can’t move through the membrane | 1\nWater molecules are small so can fit through pores in the membrane | 1\nHigher osmotic pressure/higher glucose(solute) concentration in the model cell | 1\nWater moves into the model cell by osmosis increasing its mass | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-mixed-s1"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "d",
        "type": "written",
        "prompt": "What is the name given to the type of solution in the test tube of Model C?",
        "marks": 1,
        "solution": "Isotonic | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-mixed-s1"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "e",
        "type": "written",
        "prompt": "The student repeated the experiment three times. Describe why scientists undertake multiple tests and calculate mean results.",
        "marks": 2,
        "solution": "Reduce effect of random errors | 1\nIncrease overall reliability | 1",
        "questionTypes": [
          "short_answer",
          "calculation"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-mixed-s1"
        ],
        "subtopicTagBasis": "shared_question"
      }
    ],
