    "title": "2020 Human Biology Unit 1 · Q40",
    "stem": "Active processes are involved in the formation of urine as it passes through the nephron allowing the body to regulate chemical composition of body fluids.",
    "originalStem": "Active processes are involved in the formation of urine as it passes through the nephron allowing the body to regulate chemical composition of body fluids.",
    "searchText": "Question 40 Active processes are involved in the formation of urine as it passes through the nephron allowing the body to regulate chemical composition of body fluids. State what substances are actively removed and added to the filtrate, giving reason for their movement. Joints are constructed to allow for differing types and degrees of movement. Discuss the similarities between the knee and hip joints and identify how the structure of these two joints allows for the variation in movement seen at the joints.",
    "source": "2020 Human Biology Unit 1",
    "sample": false,
    "images": [],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "State what substances are actively removed and added to the filtrate, giving reason for their movement.",
        "marks": 8,
        "solution": "Use the supplied marking key linked below to self-assess this part.",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-excretion-s1"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Discuss the similarities between the knee and hip joints and identify how the structure of these two joints allows for the variation in movement seen at the joints.",
        "marks": 12,
        "solution": "Two of the following for 1 mark each (selective reabsorption): Marks given for the first two substances. | 1-4\nGlucose\nAmino acids\nVit C\nPotassium ions\nSalts (Na+, Cl-)\nTwo of the following for 1 mark each (tubular secretion):\nMarks given for the first two substances.\nH+ ions\nElectrolytes i.e. K+, HPO4-2, SO4-\nNH3 / NH4+\nDrugs\nWastes – urea/uric acid/creatinine\nGlucose / Amino acids / Vit C are reabsorbed for their nutritional properties. | 1\nIons reabsorbed to increase blood osmolarity / assist in osmosis / move water back into blood from filtrate | 1\nH+ ions for blood pH levels | 1-2\nWastes/Drugs/Toxins could accumulate\nHigh levels can have harmful effects on the body",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-musculoskeletal-s1"
        ],
        "subtopicTagBasis": "part"
      }
    ],
