    "title": "2020 Human Biology Units 1 & 2 · Q31",
    "stem": "The diagram below shows the direction of movement of two different substances through the plasma membrane of a cell.",
    "originalStem": "The diagram below shows the direction of movement of two different substances through the plasma membrane of a cell.",
    "searchText": "Question 31 The diagram below shows the direction of movement of two different substances through the plasma membrane of a cell. (a) Identify (i) Process X (ii) Process Y (b) Which of the processes X and Y would be affected by the amount of oxygen present in the blood plasma? Justify your choice. (c) Name two other methods by which substances move across plasma cell membranes. (d) Cell membranes are composed of protein and lipid molecules. (i)On the diagram below, clearly label three cell organelles that would be involved in the synthesis of protein molecules that may form part of the cell membrane. (ii)Briefly describe how each of the organelles you have labelled contributes to protein synthesis in the cell. Enzymes are an example of a protein produced by a cell. They are used as catalysts for reactions. (e) Explain how enzymes catalyse specific reactions.",
    "source": "2020 Human Biology Units 1 & 2",
    "sample": false,
    "images": [
      {
        "src": "assets/question-diagrams/969e6d4d0f54ee32.png",
        "alt": "Original labelled diagram or graph for hb2020-u12-q31",
        "sourcePage": 10
      },
      {
        "src": "assets/question-diagrams/68e7404be3fb821f.png",
        "alt": "Original labelled diagram or graph for hb2020-u12-q31",
        "sourcePage": 11
      }
    ],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "Identify (i) Process X (ii) Process Y",
        "marks": 2,
        "solution": "(i) Process X- facilitated diffusion | 1\n(ii) Process Y- active transport | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Which of the processes X and Y would be affected by the amount of oxygen present in the blood plasma? Justify your choice.",
        "marks": 3,
        "solution": "Process Y | 1\nOxygen required for respiration | 1\nRespiration produces energy for active transport to occur | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "c",
        "type": "written",
        "prompt": "Name two other methods by which substances move across plasma cell membranes.",
        "marks": 2,
        "solution": "Any two of:\nOsmosis\nVesicular transport /endocytosis/ exocytosis/ phagocytosis/pinocytosis\nDiffusion | 1-2",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "d.i",
        "type": "written",
        "prompt": "On the diagram above, clearly label three cell organelles that would be involved in the synthesis of protein molecules that may form part of the cell membrane.",
        "marks": 3,
        "solution": "Ribosome\nRibosome\nGolgi apparatus\nGolgi apparatus\nEndoplasmic reticulum\nEndoplasmic reticulum\nMitochondria\nMitochondria\nNucleus\nNucleus\nStudents can label any 3 out of the 5 organelles labelled",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s2",
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "d.ii",
        "type": "written",
        "prompt": "Briefly describe how each of the organelles you have labelled contributes to protein synthesis in the cell.",
        "marks": 3,
        "solution": "Any 3 of the following – must match labels drawn on diagram\nNucleus has coded instructions in DNA for the type of protein to be made | 1\nMitochondria provide energy for the process | 1\nRibosomes are the actual sites on which proteins are assembled | 1\nEndoplasmic reticulum has many enzymes which catalyse the\nsynthesis of proteins on the attached ribosomes | 1\nGolgi body- packaging/secreting of proteins that have been\nproduced. | 1",
        "questionTypes": [
          "short_answer",
          "diagram"
        ],
        "subtopicIds": [
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "e",
        "type": "written",
        "prompt": "Explain how enzymes catalyse specific reactions.",
        "marks": 4,
        "solution": "Enzymes have active sites | 1\nThat are a specific shape/ configuration | 1\nComplementary to substrate/ perfect fit between active site and substrate/ lock and key | 1\nCombine to form an enzyme substrate complex | 1\nInduced fit model could also be explained.",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      }
    ],
