    "stem": "The table below gives the relative amounts of DNA present in different cells found within a human body.",
    "originalStem": "The table below gives the relative amounts of DNA present in different cells found within a human body.",
    "searchText": "Question 32 The table below gives the relative amounts of DNA present in different cells found within a human body. Cell type Amount of DNA Red blood cell 0 Skin cell 6.6 Ovum 3.3 (a) Account for the fact that the DNA content of a red blood cell is zero. (b) What is the relationship between the DNA content found in a skin cell and ovum? Give an explanation for this difference. (c) The process of meiosis is involved in the production of gametes. What are the two forms of gametogenesis called and explain how they differ in the number of gametes they produce. (d) Sperm production occurs within the testes. Name the structure in which this process takes place and give an advantage of this structure being tightly coiled. (e)State two structural differences between a sperm and an egg and for each difference explain how it helps in the process of reproduction. 1. Difference Explanation 2. Difference Explanation (f) Explain the importance of fertilisation in sexual reproduction.",
    "source": "2020 Human Biology Units 1 & 2",
