    "title": "2020 Human Biology Units 1 & 2 · Q33",
    "stem": "In humans, oxygen is carried around the body in chemical combination with an iron-based compound called haemoglobin. The chemical equation for haemoglobin combining with oxygen is shown below. Hb + O₂ → HbO₂ (this occurs in the lungs) HbO2 Hb + O2 (this occurs in the body tissues) The data below shows the relationship between the partial pressure (pp) of oxygen and the saturation of the haemoglobin molecule.",
