    "searchText": "Question 33 In humans, oxygen is carried around the body in chemical combination with an iron-based compound called haemoglobin. The chemical equation for haemoglobin combining with oxygen is shown below. Hb + O2 HbO2 (this occurs in the lungs) HbO2 Hb + O2 (this occurs in the body tissues) The data below shows the relationship between the partial pressure (pp) of oxygen and the saturation of the haemoglobin molecule. Partial pressure of oxygen (mm Hg) Saturation of haemoglobin (%) 0 0 10 10 20 25 40 70 50 82 70 93 90 96 Identify the independent variable in the information shown above. (b) Propose a hypothesis for this study. (c) Graph the results from the table above onto the grid provided. A spare grid can be found on page 41 Using data from your graph, describe the relationship between partial pressure and the percentage saturation of haemoglobin. Predict what would happen to the percentage saturation of haemoglobin if the partial pressure of oxygen was increased to 110 mmHg. Justify your prediction. Using the following information, explain how oxygen is absorbed into the bloodstream. Partial pressure of oxygen in the lungs = 100mmHg Partial pressure of oxygen in the blood that enters the lungs = 40mmHg",
