        "marks": 4,
        "solution": "Year\nAge | 2009 | 2010 | 2011 | 2012 | 2013 | 2014 | 2015 | 2016 | 2017\n15-19 | 12702 | 11865 | 11344 | 11420 | 10407 | 9204 | 8574 | 7559 | 7401\n20-24 | 43536 | 43187 | 41769 | 42367 | 41351 | 38558 | 38733 | 37022 | 36117\n40-44 | 11048 | 11710 | 12144 | 12538 | 12931 | 12106 | 12217 | 12501 | 12414\n45-49 | 572 | 604 | 661 | 736 | 670 | 777 | 910 | 1024 | 1022\nReduction in number of births from 2009-2017 | 1\nBetter understanding of contraception/ more use of contraceptives | 1\nAccept any other reasonable answer\nIncrease in number of births from 2009-2017 | 1\nWomen not having children until later age due to staying in workforce/marrying later/waiting until financially secure/ able to access ART | 1\nAccept any other reasonable answer\nIVF - Embryo inserted | 1\nGIFT- gametes inserted | 1\nIVF- implanted into uterus | 1\nGIFT- inserted into fallopian tube | 1",
