    "searchText": "Question 36 Blood is composed of fluid and cellular components. (a) Give one function of each component of blood listed in the table below. Component Function Erythrocytes Leucocytes (b) Describe the composition of plasma. (c) A person cuts their skin and it begins to bleed. Explain how platelets help with the blood clotting process. (d) The following statements refer to the circulatory system of humans. Determine if the statements are true or false and justify your choice. (i) There is little need for the muscles of the atria to be powerful. (ii) It is more efficient for the right side of the heart to be completely separated from the left.",
