    "stem": "Between 1944 and 1954 over 17,000 cases of polio were contracted in Australia and approximately 1000 deaths occurred as a result. One of the symptoms of polio is the inability to breathe easily because it affects the muscles of the respiratory system. Often patients were placed in a machine called an iron lung for an extended period. The person’s head remains outside the chamber and an airtight seal is placed around their neck. Changes in air pressure within the iron lung allow the flow of air into and out of the lungs.\n\nWhich of the following statements about the iron lung is correct?",
    "originalStem": "Which of the following statements about the iron lung is correct?",
    "searchText": "14. Which of the following statements about the iron lung is correct? (a) Breathing with an iron lung is still possible if the trachea is completely blocked. (b) During exhalation, the iron lung causes the patient’s lungs to expand. (c) During inhalation, the pressure in the iron lung is increased. (d) Inhalation and exhalation are possible even if the patient’s lung is punctured.",
