    "title": "2021 Human Biology Units 1 & 2 · Q25",
    "stem": "A group of 1594 women who had been through menopause (post-menopausal) and with diagnosed osteoporosis were recruited into a research study looking at the effect of treatment with Risedronate over a three-year period. Women were separated into two groups; one group received a placebo (inactive) treatment and the other group received a daily dose of Risedronate. Both the placebo and Risedronate were in identical forms so the women were not aware of which medication they were taking. The women kept a diary and recorded any fractures over the 3-year period. The results are shown below. Cumulative fracture rates in post-menopausal women with osteoporosis when given placebo and Risedronate over a period of 3 years Cumulative fracture rate (%) Time since taking Placebo group Risedronate group drug (months) 6 2 2 12 5 3 16 7 4 22 11 6 30 13 9 36 16 10 A valid hypothesis for this study would be",
    "originalStem": "A group of 1594 women who had been through menopause (post-menopausal) and with diagnosed osteoporosis were recruited into a research study looking at the effect of treatment with Risedronate over a three-year period. Women were separated into two groups; one group received a placebo (inactive) treatment and the other group received a daily dose of Risedronate. Both the placebo and Risedronate were in identical forms so the women were not aware of which medication they were taking. The women kept a diary and recorded any fractures over the 3-year period. The results are shown below. Cumulative fracture rates in post-menopausal women with osteoporosis when given placebo and Risedronate over a period of 3 years Cumulative fracture rate (%) Time since taking Placebo group Risedronate group drug (months) 6 2 2 12 5 3 16 7 4 22 11 6 30 13 9 36 16 10 A valid hypothesis for this study would be",
    "searchText": "25. A group of 1594 women who had been through menopause (post-menopausal) and with diagnosed osteoporosis were recruited into a research study looking at the effect of treatment with Risedronate over a three-year period. Women were separated into two groups; one group received a placebo (inactive) treatment and the other group received a daily dose of Risedronate. Both the placebo and Risedronate were in identical forms so the women were not aware of which medication they were taking. The women kept a diary and recorded any fractures over the 3-year period. The results are shown below. Cumulative fracture rates in post-menopausal women with osteoporosis when given placebo and Risedronate over a period of 3 years Cumulative fracture rate (%) Time since taking Placebo group Risedronate group drug (months) 6 2 2 12 5 3 16 7 4 22 11 6 30 13 9 36 16 10 A valid hypothesis for this study would be (a) if we give post-menopausal woman who have osteoporosis Risedronate then they will not get fractures. (b) Risedronate reduces the incidence of fractures in post-menopausal women with osteoporosis. (c) Risedronate reduces the incidence of osteoporosis in post-menopausal women. (d) post-menopausal women with osteoporosis should take Risedronate.",
