    "searchText": "Question 35 Blood groups in humans are an example of a phenotype that can be determined by multiple alleles. (a) Complete the table below showing the possible genotypes for each blood group. Blood group Genotypes A B AB O (b) The ABO blood grouping system is an example of codominance. Define this term. (c) Mrs Smith has Type A blood, but she is not sure if she is homozygous or heterozygous. Mr Smith is completely unsure of his blood type. Their children have the following blood types: Daniel has type O blood, Michael and Nathan have type A blood, Kyla has type B blood and Oliver has type AB blood. What are the possible genotypes of both Mr and Mrs Smith? Use a Punnett square to justify your answer. (d) Haemophilia is a recessive, sex-linked disorder which causes an inability to clot when bleeding. Roy and Elaine Brown were married in 1986. Neither Roy nor Elaine had haemophilia. They had two daughters and then a son. Both daughters, Alicia and Candace, had normal clotting abilities and never had any children of their own. Their son, Mike, had haemophilia and married Beth, who did not have the disease. They had two children of their own, first Ethan and then Ella. Surprisingly, Ella had haemophilia, but Ethan did not. (i) Draw the pedigree that traces the haemophilia disorder in this family. (ii) Write the genotypes for: Elaine Ethan (iii) Why is it surprising that Ella had haemophilia, but Ethan did not? (iv) If Ella has children, what do you automatically know about the phenotype of her sons?",
