    "searchText": "Question 36 The graph below shows the change in mass of a foetus over the 40 weeks of a human pregnancy. (a) Using the graph, determine the age bracket (time frame) when mass changes occur (i) the fastest (ii) the slowest (b) State the mass of the foetus at 35 weeks. Lifestyle choices of a pregnant mother can impact on the development of a foetus. (c) (i) On the graph from the previous page, sketch a line that could indicate the effect on foetal growth if a mother continued to smoke whilst pregnant. (ii) Describe the impacts that drinking alcohol may have on the developing foetus. The diagram below shows part of the placenta and the umbilical cord attached to a foetus. (d) (i) Name two substances that would be in higher concentration in the umbilical vein than in the umbilical artery. (ii) Cavity X contains maternal blood. Suggest why it is advantageous to have this blood in a cavity rather than contained within a blood vessel. (e) (i) It is possible to remove some of the fluid labelled as C in the diagram during pregnancy to examine foetal cells that are found within the fluid. Name the fluid and describe this process. (ii) State one risk associated with this method of prenatal testing. (f) Placenta Previa, or low-lying placenta, can occur in some mothers during the last part of pregnancy. The placenta often covers all the cervix. Explain why this could lead to a woman having to deliver her baby by caesarean rather than have a vaginal delivery. THIS PAGE HAS BEEN LEFT BLANK INTENTIONALLY",
