    "title": "2021 Human Biology Units 1 & 2 · Q37",
    "stem": "The diagram below shows a nephron and some of its associated blood vessels.",
    "originalStem": "The diagram below shows a nephron and some of its associated blood vessels.",
    "searchText": "Question 37 The diagram below shows a nephron and some of its associated blood vessels. (a) Describe the main process that occurs at the regions labelled C and D. (b) Explain why the process that occurs at the region labelled D requires both passive and active transport mechanisms. The table below shows the concentrations of some substances in the fluid found at A, G and E. Substance Concentration (g per 100cm3) Blood at A Fluid at G Urine at E W 0.1 0.1 0.0 X 7.0 0.0 0.0 Y 0.3 0.3 0.5 Z 0.03 0.03 2.0 (c) State which of the substances shown in the table above: (i) has molecules that are too large to fit through the walls of a capillary. (ii) is a metabolic waste product. (d) If substance Y is sodium ions, explain why the concentration is greater at E than at G. People who have acute kidney failure are given dialysis treatment. In dialysis machines the blood flows through narrow tubes made from permeable material that are surrounded by dialysis fluid. Dialysis fluid contains sodium ions. (e) Use the information from the table above to suggest what concentration of sodium ions should be in the fluid. Justify your answer. End of Section Two Section Three: Extended answer 20% This section contains four questions. You must answer two questions. Questions 38 and 39 are from Unit 1. Questions 40 and 41 are from Unit 2. Answer one question from Unit 1 and one question from Unit 2. Responses could include clearly labelled diagrams with explanatory notes; lists of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes. Unit 1 Choose either Question 38 or Question 39. Indicate the question you will answer by ticking the box next to the question. Write your answer on pages 27- 31. When you have answered your first question, turn to page 32 and indicate on that page the second question you will answer.",
