    "title": "2022 Human Biology Units 1 & 2 · Q31",
    "stem": "A group of students were investigating the effect of exercise intensity on tidal volume of the lungs. They measured the tidal volume of five of their classmates at rest and then asked each individual to complete different types of exercise, increasing in levels of intensity, for 4 minutes at a time. Immediately after completing each exercise their tidal volume was then measured with a spirometer and recorded in litres (L). The data is shown in the table below.",
    "originalStem": "A group of students were investigating the effect of exercise intensity on tidal volume of the lungs. They measured the tidal volume of five of their classmates at rest and then asked each individual to complete different types of exercise, increasing in levels of intensity, for 4 minutes at a time. Immediately after completing each exercise their tidal volume was then measured with a spirometer and recorded in litres (L). The data is shown in the table below.",
    "searchText": "Question 31 A group of students were investigating the effect of exercise intensity on tidal volume of the lungs. They measured the tidal volume of five of their classmates at rest and then asked each individual to complete different types of exercise, increasing in levels of intensity, for 4 minutes at a time. Immediately after completing each exercise their tidal volume was then measured with a spirometer and recorded in litres (L). The data is shown in the table below. Tidal volume (L) after completing 4 minutes of exercise at different intensity levels Type of Exercise Individual 1 Individual 2 Individual 3 Individual 4 Individual 5 Mean At rest 0.50 0.61 0.48 0.49 0.56 0.53 Walking 1.21 1.10 1.16 1.18 1.42 Jogging 2.25 2.23 2.18 2.04 1.98 2.14 Sprinting 2.68 2.73 2.38 2.80 2.67 2.65 (a)Outline a possible hypothesis for this investigation. (b)Identify one variable that was controlled during the students’ investigation. (c)Complete the table above by calculating the mean tidal volume for ‘Walking’. (d)Construct a graph of the average tidal volume for each type of exercise, not including the average for when the students were at rest, on the grid provided below. A spare grid is provided at the end of this Question/Answer Booklet. If you need to use it, cross out this attempt and indicate that you have redrawn it on the spare grid. (e)Suggest and explain one factor that may have affected the validity of the data. (f)Tidal volume can be defined as the amount of air moved into the lungs during the process of inspiration. Describe the process of inspiration. The students knew that an increase in the intensity of exercise causes an increase in contractions of the skeletal muscles, which requires the production of adenosine triphosphate (ATP). (g)State one chemical process that occurs during cellular respiration in the muscle cells that results in the production of ATP. The students were able to infer, from their scientific knowledge, that the increase in the tidal volume of the lungs during exercise will increase the rate of gas exchange between the blood in the capillaries and the air in the alveoli. (h)Explain why there would be an increase in the rate of gas exchange as the skeletal muscles start working harder.",
