    "title": "2022 Human Biology Units 1 & 2 · Q32",
    "stem": "The diagram below represents a simplified view of the formation of a blood clot after a blood vessel has been damaged.",
    "originalStem": "The diagram below represents a simplified view of the formation of a blood clot after a blood vessel has been damaged.",
    "searchText": "Question 32 The diagram below represents a simplified view of the formation of a blood clot after a blood vessel has been damaged. (a)Name the blood cells labelled ‘A’ and ‘B’ in the diagram. A B A broken blood vessel can lead to an infection of foreign microorganisms. This can stimulate a specific type of blood cell, known as a neutrophil, to consume the microorganisms through phagocytosis, a special form of endocytosis. (b)Describe the process by which the neutrophil consumes invading microorganisms. The X-linked genetic condition known as haemophilia means that people are unable to produce certain clotting factors that result in the production of the meshwork of protein fibres known as fibrin. The pedigree chart below shows the inheritance of haemophilia in a family. (c)State whether haemophilia is dominant or recessive. Justify your answer using evidence from the pedigree. (d)Using the letters N and n, state the genotypes of individual II-2 and II-3. II-2 II-3 (e)Is it possible for the two individuals in generation I to have a son without haemophilia? Explain your answer. (You may use a Punnett square as part of your explanation).",
    "source": "2022 Human Biology Units 1 & 2",
    "sample": false,
    "images": [
      {
        "src": "assets/question-diagrams/79fdb0dc49e4ccc0.png",
        "alt": "Original labelled diagram or graph for hb2022-u12-q32",
        "sourcePage": 13
      },
      {
        "src": "assets/question-diagrams/20e71429133f9a5e.png",
        "alt": "Original labelled diagram or graph for hb2022-u12-q32",
        "sourcePage": 14
      }
    ],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "Name the blood cells labelled ‘A’ and ‘B’ in the diagram.",
        "marks": 2,
        "solution": "A – platelets/thrombocytes | 1\nB – red blood cells/erythrocytes | 1",
        "questionTypes": [
          "short_answer",
          "diagram"
        ],
        "subtopicIds": [
          "h11-circulation-s2"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Describe the process by which the neutrophil consumes invading microorganisms.",
        "marks": 2,
        "solution": "Cell membrane folds around the microorganism (in the extracellular fluid) | 1\nThis encloses the microorganism in a vesicle (now in the cytoplasm of the cell) | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-circulation-s2"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "c",
        "type": "written",
        "prompt": "State whether haemophilia is dominant or recessive. Justify your answer using evidence from the pedigree.",
        "marks": 2,
        "solution": "Recessive | 1\nIndividual 1 and 2 in generation II are unaffected, but have an affected son/the unaffected mother in generation II has an affected son | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-circulation-s2"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "d",
        "type": "written",
        "prompt": "Using the letters N and n, state the genotypes of individual II-2 and II-3.",
        "marks": 2,
        "solution": "II-2 – XNXn | 1\nII-3 – XnY | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-circulation-s2"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "e",
        "type": "written",
        "prompt": "Is it possible for the two individuals in generation I to have a son without haemophilia? Explain your answer. (You may use a Punnett square as part of your explanation).",
        "marks": 4,
        "solution": "No | 1\nThe son will receive the X chromosome from the mother, who is homozygous recessive for haemophilia/who has two recessive alleles for haemophilia | 1-3\nand will receive Y chromosome from the father, which will not carry any alleles\nTherefore, will always be hemizygous for haemophilia/always inherit the haemophilia allele but cannot mask its effects\nCorrect Punnett square showing 100% inheritance of recessive allele by males, see example:\n\nAll males affected by recessive allele",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-circulation-s2"
        ],
        "subtopicTagBasis": "shared_question"
      }
    ],
