    "title": "2022 Human Biology Units 1 & 2 · Q34",
    "stem": "Proteins are one of the essential nutrients required for the normal functioning of cells and therefore the normal functioning of the entire human body. The production of specialised proteins called enzymes, among other things, also allows for the synthesis of other essential nutrients such as lipids and carbohydrates. Protein synthesis is a complex process that can be divided into two stages – transcription and translation.",
    "originalStem": "Proteins are one of the essential nutrients required for the normal functioning of cells and therefore the normal functioning of the entire human body. The production of specialised proteins called enzymes, among other things, also allows for the synthesis of other essential nutrients such as lipids and carbohydrates. Protein synthesis is a complex process that can be divided into two stages – transcription and translation.",
    "searchText": "Question 34 Proteins are one of the essential nutrients required for the normal functioning of cells and therefore the normal functioning of the entire human body. The production of specialised proteins called enzymes, among other things, also allows for the synthesis of other essential nutrients such as lipids and carbohydrates. Protein synthesis is a complex process that can be divided into two stages – transcription and translation. (a)State the name of the cell organelles where each of the stages of protein synthesis takes place. (b)Outline the basic structure of proteins. (c)Describe the process of transcription. Errors in the DNA code can lead to problems with protein synthesis, which can have a range of effects on normal cell functioning. (d)Explain the possible effect on metabolism if the enzymes needed for carbohydrate production could not be produced. One genetic disorder that can affect protein production is an autosomal, recessive condition known as phenylketonuria (PKU). This condition leads to a deficiency of an enzyme responsible for the breakdown of an amino acid called phenylalanine. (e)Describe what is meant by an autosomal, recessive genetic condition. (f)Determine the probability of two individuals whom are heterozygous for the recessive PKU allele having a child with the genetic condition. Show your working.",
    "source": "2022 Human Biology Units 1 & 2",
    "sample": false,
    "images": [],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "State the name of the cell organelles where each of the stages of protein synthesis takes place.",
        "marks": 2,
        "solution": "Transcription - nucleus | 1\nTranslation - ribosomes | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3",
          "h11-dna-s1"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Outline the basic structure of proteins.",
        "marks": 2,
        "solution": "Made up of long chains of amino acids | 1\nBonded together with peptide bonds | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "c",
        "type": "written",
        "prompt": "Describe the process of transcription.",
        "marks": 5,
        "solution": "DNA in the nucleus comes apart (due to RNA polymerase/helicase)\nReveals a template strand and coding strand (that are complementary to each other)\nRNA polymerase transcribes the template strand of DNA\nUsing free floating RNA nucleotides to build mRNA\nmRNA is made up of the complement of the template strand except for uracil where there would normally be thymine\nA specific sequence of bases/stop codon tells RNA polymerase to stop copying when mRNA is finished building",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-dna-s1"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "d",
        "type": "written",
        "prompt": "Explain the possible effect on metabolism if the enzymes needed for carbohydrate production could not be produced.",
        "marks": 3,
        "solution": "Carbohydrates are an important energy source/are used in cellular respiration | 1\nWithout the enzymes less carbohydrates would be produced | 1\nTherefore less energy is released and metabolism will slow | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "e",
        "type": "written",
        "prompt": "Describe what is meant by an autosomal, recessive genetic condition.",
        "marks": 2,
        "solution": "The allele is found on the autosomes/not found on the sex chromosomes | 1\nIt can be masked by a dominant allele/doesn’t show unless there are two copies of the allele | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3",
          "h11-dna-s1"
        ],
        "subtopicTagBasis": "shared_question"
      },
      {
        "id": "f",
        "type": "written",
        "prompt": "Determine the probability of two individuals whom are heterozygous for the recessive PKU allele having a child with the genetic condition. Show your working.",
        "marks": 3,
        "solution": "Correct genotypes of parents | 1\nCorrectly filled out Punnett square | 1\nCorrect probability of PKU | 1\nExample of working:\n\n25% chance of having a child with PKU",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-cells-s3",
          "h11-dna-s1"
        ],
        "subtopicTagBasis": "shared_question"
      }
    ],
