        "type": "written",
        "prompt": "Describe the structure of chromatin.",
        "marks": 1,
        "solution": "DNA molecule wrapped around histones | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-reproduction-s5",
          "h11-dna-s1"
        ],
        "subtopicTagBasis": "shared_question"
