        "type": "written",
        "prompt": "Name and describe one epigenetic factor that can alter chromatin and state the effect this factor has on gene expression.",
        "marks": 3,
        "solution": "One of the following, 1 mark for name, 1 for description and 1 mark for effect on gene expression\nAcetylation\nAn acetyl group attaches to the histone protein\nThis enhances gene expression | 1-3\nMethylation\nMethyl group attaches to DNA/CpG site on DNA\nThis inhibits gene expression | 1-3",
