    "title": "2022 Human Biology Units 1 & 2 · Q36",
    "stem": "The diagram below shows the structures of the female reproductive system.",
    "originalStem": "The diagram below shows the structures of the female reproductive system.",
    "searchText": "Question 36 The diagram below shows the structures of the female reproductive system. (a)Complete the table below, outlining the function of the structures indicated. Structure Function B D Gonorrhoea is a sexually transmitted infection (STI) that, if left untreated, can lead to blockages in the structure labelled ‘A’ in the diagram, and therefore infertility problems. (b)Identify whether gonorrhoea is a viral or bacterial infection, and state the normal treatment for this STI. (c)Suggest one way in which a gonorrhoea infection could be prevented. (d)Explain how a blockage in structure ‘A’ could lead to infertility and state one other STI that could cause infertility in females. (e)Name and explain one form of assisted reproductive technology (ART) that could best help overcome the fertility problems caused by a gonorrhoea infection.",
