        "type": "written",
        "prompt": "Complete the table below, outlining the function of the structures indicated.",
        "marks": 2,
        "solution": "B – produces ova/oestrogen/progesterone | 1\nD – (thickens/becomes more vascular) allows for zygote/blastocyst/embryo to implant/to maintain pregnancy if implantation occurs/is shed during menstruation if pregnancy doesn’t occur | 1",
