    "title": "2022 Human Biology Units 1 & 2 · Q37",
    "stem": "Parturition, or birth, is the point where the foetus is expelled from the woman’s body. After the birthing process there are a number of changes that occur in the circulatory system of the newborn.",
    "originalStem": "Parturition, or birth, is the point where the foetus is expelled from the woman’s body. After the birthing process there are a number of changes that occur in the circulatory system of the newborn.",
    "searchText": "Question 37 Parturition, or birth, is the point where the foetus is expelled from the woman’s body. After the birthing process there are a number of changes that occur in the circulatory system of the newborn. (a)The birth process is typically divided into three stages of labour. Outline any two processes/events that occur in each stage of labour. First stage: Second stage: Third stage: The foramen ovale is an opening between the two atria that is present in the foetal heart. It provides the blood with a different pathway compared to normal circulation through the heart. (b)Name and describe the function of two other structures found in the circulatory system of a foetus compared to a newborn baby. The foramen ovale usually closes shortly after the baby is born, however, there are cases when the opening does not close properly. (c)Explain the effect on normal blood flow through the heart if the foramen ovale fails to close at birth and suggest one possible symptom if this were to occur. End of Section Two Section Three: Extended answer20% This section has four questions. You must answer two questions. Questions 38 and 39 are from Unit 1. Questions 40 and 41 are from Unit 2. Answer one question from Unit 1 and one question from Unit 2. Responses could include clearly labelled diagrams with explanatory notes; list of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes. Unit 1 Choose either Question 38 or Question 39. Indicate the question you will answer by ticking the box next to the question. Write your answer on pages 30 – 34. When you have answered your first question, turn to page 35 and indicate on that page the second question you will answer.",
    "source": "2022 Human Biology Units 1 & 2",
    "sample": false,
    "images": [],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "The birth process is typically divided into three stages of labour. Outline any two processes/events that occur in each stage of labour.",
        "marks": 6,
        "solution": "First stage (any two):\nThe cervix is shortened\nThe cervix dilates\nContractions of the uterus become more regular/occur at regular intervals\nFoetus moves more deeply into the pelvis\nFormation of a single, curved passage (birth canal) | 1-2\nSecond stage (any two):\nAmnion bursts and amniotic fluid is released\nContraction of the abdominal muscles occurs\nThe baby’s head turns to face the mother’s back\nCrowning occurs\nOnce head emerges, baby rotates its head towards mother’s hips\nFoetus is expelled from the uterus/delivery of the foetus | 1-2\nThird stage (any two):\nThe umbilical cord is clamped in two places and cut\nThe uterus continues to contract forcing out the afterbirth\nUterus contractions squeeze shut the blood vessels (to prevent loss of blood) | 1-2",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-reproduction-s7"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Name and describe the function of two other structures found in the circulatory system of a foetus compared to a newborn baby.",
        "marks": 4,
        "solution": "Ductus arteriosus | 1\nDirects blood away from the lungs to flow directly into the aorta | 1\nDuctus venosus | 1\nDirects blood away from the liver into the inferior vena cava | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-reproduction-s6"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "c",
        "type": "written",
        "prompt": "Explain the effect on normal blood flow through the heart if the foramen ovale fails to close at birth and suggest one possible symptom if this were to occur.",
        "marks": 4,
        "solution": "A lot of blood would not pass into the pulmonary artery | 1\nTherefore less blood would reach the lungs | 1\nand blood would not gain enough oxygen (and release carbon dioxide) | 1\nLeads to a state of hypoxia/possible fatigue/shortness of breath/other relevant symptom | 1",
        "questionTypes": [
          "short_answer"
        ],
        "subtopicIds": [
          "h11-circulation-s1",
          "h11-reproduction-s7"
        ],
        "subtopicTagBasis": "part"
      }
    ],
