    "title": "2022 Human Biology Units 1 & 2 · Q38",
    "stem": "To allow for efficient metabolism, cells require a constant supply of nutrients and oxygen, and need to constantly remove metabolic wastes.",
    "originalStem": "To allow for efficient metabolism, cells require a constant supply of nutrients and oxygen, and need to constantly remove metabolic wastes.",
    "searchText": "Question 38 To allow for efficient metabolism, cells require a constant supply of nutrients and oxygen, and need to constantly remove metabolic wastes. (a)Explain how surface area to volume ratio, concentration gradients and the physical and chemical nature of substances can affect the exchange of materials across the cell membrane. Enzymes are specialised proteins that help cells to maintain efficient metabolism. They work best in an optimum temperature between 30 to 40°C. (b)Describe how enzymes function to optimise metabolism in the cells and explain the effect an increase in body temperature from 37°C to above 40°C can have on normal enzyme function.",
    "source": "2022 Human Biology Units 1 & 2",
    "sample": false,
    "images": [],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "Explain how surface area to volume ratio, concentration gradients and the physical and chemical nature of substances can affect the exchange of materials across the cell membrane.",
        "marks": 10,
        "solution": "Surface area to volume ratio:\nCells are very small, which gives them a large surface area compared to volume | 1\nThis means that the cell can efficiently exchange enough materials through the cell membrane to support its given volume/if the cell was larger it could not supply its given volume with enough materials through the cell membrane | 1\nConcentration gradients:\nA concentration gradient refers to a difference in concentration across the cell membrane | 1-3\nSubstances tend to passively move down a concentration gradient/from areas of high to areas of low concentration\nIf the concentration gradient across the membrane is maintained this allows for constant exchange of materials across the cell membrane\nThe greater the concentration gradient, the faster exchange of materials (or opposite concept)\nPhysical nature:\nSome molecules are larger than others, which affects their ability to pass through the small spaces in the membrane | 1\nSmall molecules can travel directly through the lipid membrane while larger molecules cannot fit/need to pass through carrier or channel proteins | 1\nChemical nature:\nThe cell membrane is made up of lipids/a phospholipid bilayer | 1\nTherefore lipid-soluble/non-polar molecules can easily diffuse through the lipid portions of the membrane (because they are not repelled by the lipid portion of the membrane) | 1\nWater soluble/polar molecules cannot pass through and need to use carrier/channel proteins to cross the membrane (because they are repelled by the lipid portion of the membrane) | 1",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-cells-s2"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Describe how enzymes function to optimise metabolism in the cells and explain the effect an increase in body temperature from 37°C to above 40°C can have on normal enzyme function.",
        "marks": 10,
        "solution": "How enzymes function:\nThey can attach to a specific substrate | 1-6\nThe active site of the enzyme will combine with the substrate\nForm an enzyme-substrate complex (before a chemical reaction occurs)\nCan work based on lock and key model/induced fit model\nEnzymes act as (organic/biological) catalysts\nTo speed up the rate of chemical reactions in the cell\nBy reducing the activation energy/reducing the energy needed to get a chemical reaction started\nThey are not used up/altered in the reaction themselves and can be reused\nEffect of temperature on enzyme function:\nThe rate of reaction will initially increase as temperature increases | 1\nAs the temperature reaches above 40°C the enzyme/active site becomes denatured | 1\nThis changes the shape of the enzyme | 1\nTherefore the enzyme cannot combine with the substrate and the reaction cannot be carried out/the enzyme cannot function as normal | 1",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-cells-s3"
        ],
        "subtopicTagBasis": "part"
      }
    ],
