    "title": "2023 Human Biology Unit 1 · Q31",
    "stem": "In 2002, a controlled trial was performed to determine if two procedures performed during arthroscopic surgery for osteoarthritis were effective in relieving knee pain. Participants were aged 75 or less, with 93% male and 60% Caucasian. 60 participants were given a placebo operation, whilst the other two-thirds had either one of the two procedures: a lavage or debridement. The trial ran for 2 years, with knee pain scores recorded. The results are shown below.",
    "originalStem": "In 2002, a controlled trial was performed to determine if two procedures performed during arthroscopic surgery for osteoarthritis were effective in relieving knee pain. Participants were aged 75 or less, with 93% male and 60% Caucasian. 60 participants were given a placebo operation, whilst the other two-thirds had either one of the two procedures: a lavage or debridement. The trial ran for 2 years, with knee pain scores recorded. The results are shown below.",
    "searchText": "Question 31 In 2002, a controlled trial was performed to determine if two procedures performed during arthroscopic surgery for osteoarthritis were effective in relieving knee pain. Participants were aged 75 or less, with 93% male and 60% Caucasian. 60 participants were given a placebo operation, whilst the other two-thirds had either one of the two procedures: a lavage or debridement. The trial ran for 2 years, with knee pain scores recorded. The results are shown below. Procedure (Average Scores on Knee Pain Scale) Time (Weeks) Placebo Lavage Debridement 0 60 61 58 26 57 59 56 78 52 56 51 104 55 55 53 Explain why the researchers included a placebo operation in this study. State whether the results of this study would be applicable to everyone with knee pain. Justify your answer. Graph the results from the 2002 trial on the grid provided below. A spare grid is provided at the end of this Question/Answer Booklet. If you need to use it, cross out this attempt and indicate that you have redrawn it on the spare grid By the age of 70, everyone will have some symptoms of osteoarthritis. Outline the cause of the joint pain that osteoarthritis sufferers experience. Osteoporosis is another musculoskeletal disease associated with ageing. How does osteoporosis differ from osteoarthritis?",
