    "title": "2023 Human Biology Unit 1 · Q32",
    "stem": "The human body is made up of approximately 37.2 trillion cells, each of these with a set of specific cell organelles that maintain life processes. The production of proteins is one such important process occurring within a cell.",
    "originalStem": "The human body is made up of approximately 37.2 trillion cells, each of these with a set of specific cell organelles that maintain life processes. The production of proteins is one such important process occurring within a cell.",
    "searchText": "Question 32 The human body is made up of approximately 37.2 trillion cells, each of these with a set of specific cell organelles that maintain life processes. The production of proteins is one such important process occurring within a cell. (a)Briefly outline the function of the following organelles regarding protein production. Organelle Function Nucleus Ribosomes Golgi body (b)Proteins can become integrated within the cell membrane. In the space below, draw a fully labelled diagram of the fluid mosaic model to represent the structure of a cell membrane. The diagram below is a representation of cellular respiration within a cell. (c)Name the processes, as well as the corresponding amount of ATP produced, at the locations identified by the numbers 1, 2 and 3. Location Process Amount of ATP produced 1 2 3 Molecular malfunctions within cell organelles are the cause of many human illnesses, such as Mitochondrial Disease. The main symptoms of Mitochondrial Disease are muscle fatigue and weakness. (d)Give a reason why muscle is the tissue most affected by mitochondrial disease. (e) Describe how ineffective mitochondria would affect a cell’s general function within the body.",
