    "stem": "Penicillin was discovered in 1928, with the first patient treated with the antibiotic 20 years later. It works through the process of enzyme inhibition, stopping bacteria from synthesising a cell wall and therefore causing it to die.",
    "originalStem": "Penicillin was discovered in 1928, with the first patient treated with the antibiotic 20 years later. It works through the process of enzyme inhibition, stopping bacteria from synthesising a cell wall and therefore causing it to die.",
    "searchText": "Question 33 Penicillin was discovered in 1928, with the first patient treated with the antibiotic 20 years later. It works through the process of enzyme inhibition, stopping bacteria from synthesising a cell wall and therefore causing it to die. (a)Explain how an enzyme reaction would differ in the presence of an enzyme inhibitor. (b)Several other factors can also affect the function of enzymes. Match the appropriate reactivity graphs to the factors identified below. Graph A Graph B Graph C Graph D Substrate concentration: Temperature: pH: Enzyme concentration: (c)Some enzymes require prior activation before they can work effectively. Identify the cell in the stomach lining that produces pepsinogen and outline how it becomes an active enzyme. A diagram of the parts of the stomach is shown below. (d)Unlike the rest of the alimentary canal, the stomach has a third muscle layer. State the name of this muscle layer and outline why it is found in the stomach.",
    "source": "2023 Human Biology Unit 1",
    "sample": false,
