    "title": "2023 Human Biology Unit 1 · Q34",
    "stem": "Helicobacter pylori is a bacterium that damages the protective mucous coating of the digestive system. This damage can lead to the formation of peptic ulcers in the duodenum.",
    "originalStem": "Helicobacter pylori is a bacterium that damages the protective mucous coating of the digestive system. This damage can lead to the formation of peptic ulcers in the duodenum.",
    "searchText": "Question 34 Helicobacter pylori is a bacterium that damages the protective mucous coating of the digestive system. This damage can lead to the formation of peptic ulcers in the duodenum. (a)Why are peptic ulcers more likely to be found in the duodenum? (b)H. pylori infections can also cause chronic diarrhoea in early infancy. Define diarrhoea and explain its cause. LDL cholesterol, often referred to as “bad” cholesterol, is transported into cells of the body through vesicular transport. (c)Outline the steps involved in taking up cholesterol into a cell. (d)Is the uptake of cholesterol considered to be a passive or active process? Justify your answer. (e)Most cholesterol is produced in the liver. What digestive substance is produced using cholesterol from the liver and where is it stored? Explain how a blockage in the duct leading into the small intestine would affect digestive function.",
    "source": "2023 Human Biology Unit 1",
