    "title": "2023 Human Biology Unit 1 · Q36",
    "stem": "Approximately 10% of a person’s body weight is made up of blood, equating to about 5L. A loss of 40% or more of your blood volume will result in death, with blood transfusions required to stop this from occurring.",
    "originalStem": "Approximately 10% of a person’s body weight is made up of blood, equating to about 5L. A loss of 40% or more of your blood volume will result in death, with blood transfusions required to stop this from occurring.",
    "searchText": "Question 36 Approximately 10% of a person’s body weight is made up of blood, equating to about 5L. A loss of 40% or more of your blood volume will result in death, with blood transfusions required to stop this from occurring. (a)Outline how molecules found on the surface of red blood cells and in the plasma are important in blood transfusions. One of the functions of blood is to transport oxygen to cells and carbon dioxide away from cells. (b)Explain how carbon dioxide is transported in the blood. Carbon dioxide is a cellular waste removed from the body via the lungs. Other wastes created in the body are removed via urine. Normal urine is composed of water, solutes and wastes, with approximately 2% being urea. (c)What would you expect to happen to the percentage of urea in a person’s urine if they ate a high-protein diet? Justify your answer. Nutrients and wastes are transferred between cells and extracellular space via transport mechanisms. (d)Complete the table below identifying the transport mechanism associated with each of the stated processes. Process Transport Mechanism Water-soluble vitamins being absorbed into the blood capillaries of the villi Uptake of amino acids into the villi of the small intestine after a meal Water movement from the kidney tubules into the blood (e) Explain how fats are absorbed into the villi of the small intestine.",
