    "title": "2023 Human Biology Unit 1 · Q38",
    "stem": "In every living cell, enzyme controlled chemical reactions take place continuously and are often linked together.",
    "originalStem": "In every living cell, enzyme controlled chemical reactions take place continuously and are often linked together.",
    "searchText": "Question 38 In every living cell, enzyme controlled chemical reactions take place continuously and are often linked together. State the name given to this set of reactions and describe the two types that occur in the body. Give an example of each type. Cells require nutrients in order to undertake life processes, such as growth and repair. The digestive system extracts these nutrients from the food we eat through chemical and mechanical digestion. The mouth, stomach and small intestine utilise chemical and mechanical digestion. Differentiate between the two types of digestion and list the functions associated with the three named parts of the digestive system.",
    "source": "2023 Human Biology Unit 1",
    "sample": false,
