    "title": "2023 Human Biology Unit 1 · Q39",
    "stem": "Crohn’s disease is an autoimmune condition which damages the lining of the small intestine, leading to inflammation.",
    "originalStem": "Crohn’s disease is an autoimmune condition which damages the lining of the small intestine, leading to inflammation.",
    "searchText": "Question 39 Crohn’s disease is an autoimmune condition which damages the lining of the small intestine, leading to inflammation. Describe the lining of a healthy small intestine and outline why an individual with unmanaged Crohn’s tend to lose weight. Emphysema is a lung disease most often attributed to smoking. People with emphysema have damaged alveoli and decreased blood flow. Explain how the structure of the lungs allow for efficient gas exchange. Predict some of the symptoms that emphysema patients would exhibit. Question number: Question number: Question number: Question number: Question number: Part 2 Choose either Question 40 or Question 41. Indicate the question you will answer by ticking the box next to the question. Write your answer on the pages provided.",
    "source": "2023 Human Biology Unit 1",
    "sample": false,
    "images": [],
    "tables": [],
    "parts": [
      {
        "id": "a",
        "type": "written",
        "prompt": "Describe the lining of a healthy small intestine and outline why an individual with unmanaged Crohn’s tend to lose weight.",
        "marks": 8,
        "solution": "Inner lining/mucosa has folds that extend into the interior | 1\nMucosa has small finger-like projections/folding called villi | 1\nVilli contain microvilli | 1\nInside is a lacteal (lymph capillary) surrounded by blood capillaries | 1\nVilli are thin / 1 cell thick | 1\nVilli is the site of nutrient absorption | 1\nDamage to the villi mean nutrients would not be absorbed into the body | 1\nSurface area for absorption has decreased | 1",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-digestion-s1"
        ],
        "subtopicTagBasis": "part"
      },
      {
        "id": "b",
        "type": "written",
        "prompt": "Explain how the structure of the lungs allow for efficient gas exchange. Predict some of the symptoms that emphysema patients would exhibit.",
        "marks": 12,
        "solution": "Lungs have a large internal surface area | 1\nSo large amounts of gas can be exchanged in a short time | 1\nAlveolus is well supplied with blood vessels | 1\nBlood vessels are in close proximity to alveoli | 1\nContinuous blood flow maintains concentration difference between alveoli and blood | 1\nwalls of alveolus are thin / 1 cell thick | 1\nReduces the distance gases have to travel | 1\nLungs positioned deep inside the body | 1\nPrevents excessive moisture evaporation | 1\nWhich is needed as gases must be dissolved in fluid in order to diffuse | 1\nAny two of the following symptoms:\nCoughing and/or wheezing\nIncreased production of mucus\nShortness of breath\nTightness of chest | 1-2",
        "questionTypes": [
          "extended_response"
        ],
        "subtopicIds": [
          "h11-respiratory-s1"
        ],
        "subtopicTagBasis": "part"
      }
    ],
