        "type": "written",
        "prompt": "Outline the structure of a nephron beginning at the renal corpuscle. State the activities which occur at each region.",
        "marks": 14,
        "solution": "Renal corpuscle consists of the Bowman’s / glomerular capsule | 1\nwhich almost completely encloses the glomerulus | 1\nFilters the blood / glomerular filtration occurs | 1\nForms the filtrate\nNext is the proximal convoluted tubule | 1\nwhere passive reabsorption of potassium/chloride/bicarbonate ions | 1\nActive reabsorption of glucose/sodium/amino acids | 1\nOsmotic reabsorption of water occurs | 1\nLeads into the loop of Henle | 1\nActive reabsorption of sodium ions / chlorine ion | 1\nOsmosis of water occurs | 1\nFollowed by the distal convoluted tubule | 1\nSecretion of hydrogen/potassium ions/creatinine/certain drugs | 1\nJoins to a collecting duct | 1\nactive reabsorption of water | 1",
        "questionTypes": [
          "extended_response"
        ],
